"""Decoupled test oracle synthesis to eliminate coverage bias."""

from __future__ import annotations

from mutant_rl.schemas.mutation import CoupledMutation


class DecoupledOracleSynthesizer:
    """Generates independent reproduction test harnesses targeting coupled mutations."""

    def synthesize_reproduction_test(
        self, mutation: CoupledMutation, module_name: str = "app"
    ) -> str:
        """Constructs a deterministic regression test exercising the mutated interfaces."""
        test_code_lines = [
            '"""Synthesized regression oracle generated by Mutant-RL."""',
            "import pytest",
            "",
            f"def test_{mutation.name}_regression():",
        ]

        if mutation.touches_config:
            test_code_lines.extend(
                [
                    "    # Verifies configuration and runtime alignment",
                    "    from pathlib import Path",
                    "    import yaml",
                    "",
                    "    config_file = Path('config.yaml')",
                    "    if config_file.exists():",
                    "        with open(config_file) as f:",
                    "            cfg = yaml.safe_load(f)",
                    "        assert not any(k.startswith('legacy_') for k in cfg.keys()), (",
                    "            'Legacy configuration key detected'",
                    "        )",
                ]
            )
        else:
            test_code_lines.extend(
                [
                    "    # Exercises coupled cross-file boundary",
                    f"    # Target mutation: {mutation.name}",
                    "    try:",
                    f"        from {module_name} import run_pipeline",
                    "        result = run_pipeline()",
                    "        assert result is not None, 'Pipeline returned unexpected None'",
                    "    except TypeError as e:",
                    "        pytest.fail(f'Cross-module contract violation detected: {e}')",
                ]
            )

        return "\n".join(test_code_lines) + "\n"
